import{state}from"./state.js";import{renderAll}from"./ui.js";import{completeTaskOnServer,requestTaskCompletionOnServer}from"./api.js";import{showToast,showConfirm,showMobileEventNotification,escapeHtml}from"./utils.js";import{applyServerFamilyData,checkDailyCoinLimit,checkFrequency,flushPendingSave,getActingChildId}from"./action-helpers.js";import{triggerTaskAnimation}from"./motion-feedback.js";async function commitTaskCompletion(e,i){await flushPendingSave();const t=await completeTaskOnServer(e.id,i);t.success&&t.data?(applyServerFamilyData(t.data,{currentChildId:i}),renderAll(),showMobileEventNotification(`+${e.coins} мон. начислено!`,"success","Balance updated"),triggerTaskAnimation()):showToast(t.error||"Не удалось начислить монеты","error")}async function commitTaskRequest(e,i){await flushPendingSave();const t=await requestTaskCompletionOnServer(e.id);t.success&&t.data?(applyServerFamilyData(t.data,{currentChildId:i}),renderAll(),document.querySelector('.nav__btn[data-tab="requests"]')?.click(),showMobileEventNotification("Заявка отправлена!","success","Новая заявка"),triggerTaskAnimation()):showToast(t.error||"Не удалось отправить заявку","error")}export function earnCoins(e){const i=state.tasks.find(i=>i.id==e);if(!i)return;const t=state.isAdmin?state.currentChildId:state.children[0]?.id||null;if(!t){const e=state.isAdmin&&0===state.children.length?"Сначала добавьте ребенка":"Сначала выберите ребенка";return showToast(e,"error")}const n=[checkFrequency(i,t),checkDailyCoinLimit(t,i.coins)].filter(Boolean),o=()=>{commitTaskCompletion(i,t)};if(n.length>0)return showConfirm("Превышен лимит",`${n.join(". ")}. Все равно начислить?`,{onConfirm:o});const r=`Подтвердить выполнение задания "${escapeHtml(i.name)}" за ${i.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>?`;showConfirm("Выполнить задание?",r,{onConfirm:o})}export function requestCoins(e){const i=state.tasks.find(i=>i.id==e);if(!i)return;const t=getActingChildId();if(!t)return showToast("Сначала выберите ребенка","error");const n=[checkFrequency(i,t),checkDailyCoinLimit(t,i.coins)].filter(Boolean);if(n.length>0)return showConfirm("Лимит исчерпан",n.join(". "),{cancelLabel:"Понятно",hideConfirm:!0});const o=`"${escapeHtml(i.name)}" за ${i.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>`;showConfirm("Отправить заявку?",o,{onConfirm:()=>{commitTaskRequest(i,t)}})}